begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(20);
select has_table('private','role_audit','Role audit exists');
select ok((select relrowsecurity from pg_class where oid='private.role_audit'::regclass),'Audit RLS enabled');
select ok((select relrowsecurity from pg_class where oid='private.account_roles'::regclass),'Existing role RLS preserved');
select is(has_table_privilege('authenticated','private.account_roles','SELECT,INSERT,UPDATE,DELETE'),false,'No direct client roles');
select is(has_table_privilege('authenticated','private.role_audit','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),false,'No direct client audit access');
select is(has_table_privilege('rollcall_admin_executor','private.role_audit','UPDATE,DELETE,TRUNCATE'),false,'Executor cannot mutate audit history');
select is(has_table_privilege('rollcall_admin_executor','private.profile_private','SELECT'),false,'Executor cannot read private ages');
select is(has_table_privilege('rollcall_admin_executor','private.event_locations','SELECT'),false,'Executor cannot read residential addresses');
select is(has_table_privilege('rollcall_admin_executor','private.event_invitations','SELECT'),false,'Executor cannot read room codes');
select is(has_schema_privilege('rollcall_admin_executor','auth','USAGE'),false,'Executor has no raw Auth schema access');
select is((select rolcanlogin from pg_roles where rolname='rollcall_admin_executor'),false,'Executor cannot log in');
select is((select rolbypassrls from pg_roles where rolname='rollcall_admin_executor'),false,'Executor cannot bypass RLS');
select is(pg_has_role('authenticated','rollcall_admin_executor','MEMBER'),false,'Clients cannot assume executor');
select is(has_function_privilege('anon','public.my_permissions()','EXECUTE'),false,'Anonymous permission lookup denied');
select is(has_function_privilege('authenticated','private.bootstrap_superadmin(uuid)','EXECUTE'),false,'No client bootstrap');
select is(has_function_privilege('authenticated','private.confirmed_admin_actor()','EXECUTE'),false,'Identity helper is internal');
select is(has_function_privilege('authenticated','private.admin_account_confirmed(uuid)','EXECUTE'),false,'Account helper is internal');
select is((select prosecdef from pg_proc where oid='public.change_admin_role(uuid,text)'::regprocedure),false,'Public wrapper is invoker-only');
select is((select rolname::text from pg_roles where oid=(select proowner from pg_proc where oid='private.change_admin_role(uuid,text)'::regprocedure)),'rollcall_admin_executor','Role changes use narrow executor');
select throws_ok('truncate private.role_audit','42501','Role audit is append-only.','Audit truncate is blocked');
select * from finish();
rollback;
